CREATE TABLE IF NOT EXISTS officer_direct(id INTEGER PRIMARY KEY AUTOINCREMENT,unit_id TEXT NOT NULL REFERENCES units(id),full_name TEXT NOT NULL,whatsapp TEXT NOT NULL,position TEXT NOT NULL,term_start TEXT NOT NULL,term_end TEXT NOT NULL,photo_key TEXT NOT NULL,card_token TEXT NOT NULL UNIQUE,consent_at TEXT NOT NULL,revoked_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(term_start<=term_end)); CREATE INDEX IF NOT EXISTS officer_direct_unit ON officer_direct(unit_id);